170→        >
171→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
172→        </button>
173→      </div>
174→    );
175→  }
176→
177→  return (
178→    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
179→      {/* Workspace switcher */}
