161→function toPersistedAgent(agent: AgentState): PersistedAgent {
162→  return {
163→    id: agent.agentId,
164→    state: {
165→      agentId: agent.agentId,
166→      status: agent.status,
167→      tmuxSession: agent.tmuxSession,
168→      label: agent.label,
169→      createdAt: agent.createdAt,
