177→/**
178→ * Compact a message history by deduplicating cumulative snapshots.
179→ * Keeps only the last version of each assistant/user message ID.
180→ * Called on restore to shrink legacy bloated histories.
181→ */
182→function compactHistory(history: ServerMessage[]): ServerMessage[] {
183→  // Build a map of msgId → last index
184→  const lastIndex = new Map<string, number>();
185→  for (let i = 0; i < history.length; i++) {
186→    const id = getRelayMessageId(history[i]);
187→    if (id) lastIndex.set(id, i);
188→  }
189→  // Keep only messages that are either non-deduplicable or the last occurrence
190→  return history.filter((msg, i) => {
191→    const id = getRelayMessageId(msg);
192→    if (!id) return true; // non-relay or no message ID — always keep
193→    return lastIndex.get(id) === i;
194→  });
195→}
