  idle: "idle",
  spawning: "spawning...",
  connected: "connected",
  thinking: "thinking...",
  done: "done",
  disconnected: "disconnected",
  error: "error",
};

export function StatusBar({
  connected,
  status,
  showRaw,
  onToggleRaw,
  showTasks,
  onToggleTasks,
  showDiffs,
  onToggleDiffs,
  onToggleSidebar,
  onOpenSfxSettings,
